'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isDataSet = require( '@stdlib/plot/vega/base/assert/is-dataset' );
var filledBy = require( '@stdlib/array/base/filled-by' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var objarrays2tidy = require( './../lib' );


// FUNCTIONS //

/**
* Returns an object.
*
* @private
* @param {NonNegativeInteger} i - index
* @returns {Object} object
*/
function clbk( i ) {
	return {
		'a': i,
		'b': i
	};
}


// MAIN //

bench( format( '%s:len=10', pkg ), function benchmark( b ) {
	var mapping;
	var names;
	var x;
	var i;
	var v;

	mapping = {
		'a': 'x',
		'b': 'y'
	};
	names = [ 'data1', 'data2' ];
	x = [ filledBy( 10, clbk ), filledBy( 10, clbk ) ];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = objarrays2tidy( x, names, mapping );
		if ( typeof v !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isDataSet( v[ 0 ] ) || !isDataSet( v[ 1 ] ) ) {
		b.fail( 'should return a list of data sets' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
